  const input=document.createElement('input');input.type='search';input.className='search-select-input';input.autocomplete='off';input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-expanded','false');
  const fieldLabel=sel.closest('.field')?.querySelector('label')?.textContent?.trim();
