function allDates(){const src=page==='actions'?[...rows('actions'),...rows('weeklyPlans')]:page==='productionForecast'?rows('dailyProductionForecast'):rows('actuals');return src.map(rowDate).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d))}
function availableYears(){const targetYears=[...rows('teamTargets'),...rows('targets')].map(x=>String(x.Year||'')).filter(y=>/^\d{4}$/.test(y));return [...new Set([...allDates().map(x=>x.slice(0,4)),...targetYears,String(new Date().getFullYear())])].sort()}
function availablePeriods(){const dates=allDates();if(filterState.periodMode==='day')return [...new Set(dates)].sort().map(v=>[v,v]);if(filterState.periodMode==='week')return [...new Set(dates.map(isoWeek))].filter(Boolean).sort().map(v=>[v,v.replace(/^W/,'WEEK ')]);const months=[...dates.map(d=>d.slice(0,7))];if(page!=='actions'&&page!=='productionForecast')for(const t of [...rows('teamTargets'),...rows('targets')]){const y=String(t.Year||''),m=Number(t.Month);if(/^\d{4}$/.test(y)&&m>=1&&m<=12)months.push(y+'-'+String(m).padStart(2,'0'))}return [...new Set(months)].sort().map(v=>[v,new Date(v+'-01T00:00:00').toLocaleString('en-US',{month:'short'}).toUpperCase()+'/'+v.slice(0,4)])}function selected(key,value){return (filterState[key]||[]).includes(String(value))}
function multiFilter(key,label,options){const vals=filterState[key]||[],all=!vals.length,summary=all?'ทั้งหมด':vals.length<3?vals.map(v=>(options||[]).find(o=>String(o[0])===String(v))?.[1]||v).join(', '):vals.length+' รายการ';return '<div class="filter-control" data-filter-holder="'+key+'"><label>'+esc(label)+'</label><details class="multi-filter"><summary data-filter-summary="'+key+'" title="'+esc(label)+': '+esc(summary)+'"><span>'+esc(summary)+'</span></summary><div class="multi-menu"><input type="search" class="filter-search" data-pick-search="'+key+'" placeholder="ค้นหาในรายการ"><label class="multi-option all"><input type="checkbox" data-pick-all="'+key+'" '+(all?'checked':'')+'> All / ทั้งหมด</label>'+(options||[]).map(([v,l])=>'<label class="multi-option" data-filter-option="'+key+'"><input type="checkbox" data-pick="'+key+'" value="'+esc(v)+'" '+(selected(key,v)?'checked':'')+'> '+esc(l)+'</label>').join('')+'</div></details></div>'}function canonicalTargetChannel(value){const raw=String(value||'').trim();const hit=channelUniqueRows().find(c=>String(c.Channel_Code||'').trim()===raw||String(c.Channel_Name||'').trim()===raw);return hit?String(hit.Channel_Code||'').trim():raw}
