 return {years:availableYears().map(x=>[x,x]),periods:availablePeriods(),channels:channel,sales:sale,types:types.map(x=>[x,x]),parts:parts.map(x=>[x,x]),subparts:subparts.map(x=>[x,x]),groupProducts:groupRows,products:product,statuses:[['OPEN','Open'],['IN_PROGRESS','In Progress'],['DONE','Closed'],['CANCELLED','Cancelled']],targetYears,targetMonths,targetChannels:targetChannelOptions()}
