function normalizeWeeklyKey(value,date=''){const raw=String(value??'').normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g,'').trim().toUpperCase().replace(/^WEEK\s*/,'W').replace(/\s+/g,'');const m=raw.match(/^W?(\d{1,2})\/(\d{4})$/);if(m)return `W${String(Number(m[1])).padStart(2,'0')}/${m[2]}`;return date?isoWeek(date):''}
function passesWeeklyPlanFilters(r){const item=rows('items').find(i=>String(i.Item_Code||'')===String(r.Item_Code||''))||{},customer=rows('customers').find(c=>String(c.Customer_Code||'')===String(r.Customer_Code||''))||{},saleRow=rows('sales').find(x=>String(x.Sale_ID||'')===String(r.Sale_ID||''))||{},channel=customer.Channel||r.Channel||saleRow.Channel||saleRow.Team||'',sale=r.Sale_ID||customer.Assigned_Sale_ID||'',type=r.Product_Type||item.Product_Type||'',part=r.PART||item.PART||'',sub=r.SUB_PART||item.SUB_PART||'',groupProduct=r.Group_Product_ID||item.Group_Product_ID||'';const checks=[['channels',channel],['sales',sale],['types',type],['parts',part],['subparts',sub],['groupProducts',groupProduct],['products',r.Item_Code||'']];return checks.every(([key,value])=>!(filterState[key]||[]).length||filterState[key].map(String).includes(String(value)))}
const crmRowIndexCache=new Map();
