  const week=$('#wWeek').value,groups=[...document.querySelectorAll('[data-week-row]')],objects=[],root=$('#weeklyPlanRows'),originalRefs=JSON.parse(root?.dataset.originalPlanRefs||'[]'),retainedRefs=new Set(groups.flatMap(g=>[...g.querySelectorAll('[data-w-detail]')].map(el=>`${el.dataset.planId||''}|${Number(el.dataset.sheetRow||0)}`))),deleteRefs=originalRefs.filter(x=>!retainedRefs.has(`${x.Plan_ID||''}|${Number(x._row||0)}`));
