  const head=[...table.tHead.rows];if(head.length<3)continue;
  const h1=head[0].getBoundingClientRect().height||0,h2=head[1].getBoundingClientRect().height||0,h3=head[2].getBoundingClientRect().height||0,forecast=table.querySelector('.weekly-forecast-row')?.getBoundingClientRect().height||0;
  table.style.setProperty('--wf-head-2',h1+'px');
  table.style.setProperty('--wf-head-3',(h1+h2)+'px');
  table.style.setProperty('--wf-head-4',(h1+h2+h3)+'px');
  table.style.setProperty('--wf-contact-top',(h1+h2+h3+forecast)+'px');
  let left=0;const identityCells=[...head[0].cells].slice(0,4);
