 return {...source,Plan_ID:id('WPLAN'),Week_Key:week,Week_Start:range.start,Week_End:range.end,Plan_Date:date,Contact_Completed:0,Contact_Order_Qty:'',Contact_Order_Date:'',Version:1,Saved_By:me,Saved_At:new Date().toISOString(),Data_Status:'LIVE',_row:0}
