function actionDetailFormV2(existing){const sale=rows('sales').find(s=>s.Sale_ID===existing.Sale_ID),customer=actionCustomerName(existing),item=rows('items').find(i=>i.Item_Code===existing.Item_Code)||{},uom=existing.Plan_UOM||'MT',planRaw=existing.Plan_Qty!==''&&existing.Plan_Qty!=null?existing.Plan_Qty:(existing.Plan_MT??existing.Expected_Qty_MT),plan=Number(planRaw)||0,closedRaw=existing.Closed_Sales_Qty!==''&&existing.Closed_Sales_Qty!=null?existing.Closed_Sales_Qty:existing.Closed_Sales_MT,closed=Number(closedRaw)||0;openModal(`<div class="row space"><div><h3>รายละเอียด Action</h3><div class="smallmuted">${esc(customer)}</div></div><button class="btn" id="modalClose">ปิด</button></div><div class="formgrid"><div class="field"><label>พนักงาน</label><input readonly value="${esc(sale?.Sale_Name||existing.Sale_ID)}"></div><div class="field"><label>Channel</label><input readonly value="${esc(existing.Channel||sale?.Channel||sale?.Team||'')}"></div><div class="field"><label>กลุ่มสินค้า</label><input readonly value="${esc([existing.Product_Type||item.Product_Type,existing.PART||item.PART,existing.SUB_PART||item.SUB_PART,existing.Group_Product_Name].filter(Boolean).join(' / '))}"></div><div class="field"><label>วันที่กำหนด</label><input readonly value="${esc(normDate(existing.Due_Date))}"></div><div class="field"><label>ประเภท Action</label><input readonly value="${esc(existing.Action_Type||'')}"></div><div class="field"><label>ประเภทลูกค้า</label><input readonly value="${esc(existing.Prospect_Name?'Prospect':'ลูกค้าเก่า')}"></div><div class="field"><label>Plan</label><input readonly value="${fmt(plan,3)} ${esc(uom)}${existing.Plan_MT!==''&&existing.Plan_MT!=null?' · '+fmt(existing.Plan_MT,3)+' MT':''}"></div><div class="field"><label>สถานะ</label><select id="dStatus">${['OPEN','IN_PROGRESS','DONE','CANCELLED'].map(s=>`<option ${existing.Status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>ปิดการขาย (${esc(uom)} · หน่วยเดียวกับ Plan)</label><input id="dClosed" type="number" min="0" step="0.001" value="${esc(closed)}"></div><div class="field wide"><label>Action : รายละเอียด</label><textarea id="dResult">${esc(existing.Result||'')}</textarea></div><div class="field wide"><label>Next Action : รายละเอียด</label><textarea id="dNext">${esc(existing.Next_Action||'')}</textarea></div><div class="field"><label>Next Action : วันที่กำหนด</label><input id="dNextDate" type="date" value="${esc(normDate(existing.Next_Action_Date))}"></div><div class="field wide"><label>Comment แนะนำจากหัวหน้า</label><textarea id="dComment">${esc(existing.Manager_Comment||'')}</textarea></div></div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="dSave">บันทึก</button></div>`);$('#dSave').onclick=()=>saveActionDetailV2(existing)}
async function saveActionDetailV2(existing){try{const old=rows('actions').find(a=>a.Action_ID===existing.Action_ID)||existing,uom=old.Plan_UOM||'MT',qty=Number($('#dClosed').value)||0,meta=actionUomMeta(old.Product_Type,old.PART,old.SUB_PART).find(x=>x.key===String(uom).toUpperCase()),kg=meta?.uniform?meta.factor:Number(old.KG_Per_UOM)||0,closedMt=kg>0?qty*kg/1000:'';const o={...old,Status:$('#dStatus').value,Closed_Sales_MT:closedMt,Closed_Sales_Qty:qty,Closed_Sales_UOM:uom,Result:$('#dResult').value,Next_Action:$('#dNext').value,Next_Action_Date:$('#dNextDate').value,Manager_Comment:$('#dComment').value,Manager_Comment_By:me,Manager_Comment_At:new Date().toISOString(),Updated_By:me,Updated_At:new Date().toISOString()};await updateRow(TAB.actions,o._row,o);await append(TAB.actionHistory,[{History_ID:id('HIS'),Action_ID:o.Action_ID,Changed_At:new Date().toISOString(),Changed_By:me,Event_Type:'UPDATE',Old_Status:old.Status||'',New_Status:o.Status,Old_Due_Date:old.Due_Date||'',New_Due_Date:old.Due_Date||'',Old_Plan_MT:old.Plan_MT||'',New_Plan_MT:old.Plan_MT||'',Old_Closed_Sales_MT:old.Closed_Sales_MT||'',New_Closed_Sales_MT:o.Closed_Sales_MT,Old_Next_Action:old.Next_Action||'',New_Next_Action:o.Next_Action,Manager_Comment:o.Manager_Comment,Manager_Comment_By:me,Manager_Comment_At:o.Manager_Comment_At,Note:`Actual entered in ${uom}; Next action date: ${o.Next_Action_Date||''}`}]);closeModal();ping('บันทึก Action แล้ว');await loadDb()}catch(e){ping(e.message,true)}}
function itemGroupOptions(key){return [...new Set(categoryMasterRows().map(i=>i[key]).filter(Boolean))].sort()}
function actionBatchForm(){const channels=active(rows('channels'));openModal(`<div class="row space"><div><h3>วางแผน Action ล่วงหน้า</h3><div class="smallmuted">เลือกพนักงาน/กลุ่มสินค้าครั้งเดียว แล้วเพิ่มรายละเอียด Plan ได้หลายรายการและบันทึกพร้อมกัน</div></div><button class="btn" id="modalClose">ปิด</button></div><div class="section-title">ข้อมูลส่วนกลางของ Action</div><div class="formgrid"><div class="field"><label>พนักงาน</label><select id="baSale">${active(rows('sales')).map(s=>`<option value="${esc(s.Sale_ID)}">${esc(s.Sale_Name)}</option>`).join('')}</select></div><div class="field"><label>Channel / Team จาก Sale Master</label><input id="baChannel" readonly></div><div class="field"><label>Product Type</label><select id="baType"><option value="">เลือก Product Type</option>${itemGroupOptions('Product_Type').map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>PART</label><select id="baPart"><option value="">เลือก PART</option></select></div><div class="field"><label>SUB-PART</label><select id="baSub"><option value="">เลือก SUB-PART</option></select></div></div><div class="row space" style="margin:18px 0 10px"><div><div class="section-title">รายละเอียด Plan</div><div class="smallmuted">ลูกค้าเก่าเลือกจาก Master/กลุ่มสินค้าที่สนใจ · Prospect กรอกชื่อเอง · ยอดปิดการขายบันทึกเป็นหน่วยเดียวกับ Plan</div></div><button type="button" class="btn" id="addActionPlan">+ เพิ่ม Plan</button></div><div id="actionPlanRows"></div><div class="row" style="justify-content:flex-end;margin-top:16px"><button class="btn primary" id="saveActionBatch">บันทึก Plan ทั้งหมด</button></div>`);$('#baSale').onchange=()=>$('#baChannel').value=rows('sales').find(x=>x.Sale_ID===$('#baSale').value)?.Channel||rows('sales').find(x=>x.Sale_ID===$('#baSale').value)?.Team||'';$('#baSale').onchange();$('#baType').onchange=()=>fillGroupParts();$('#baPart').onchange=()=>fillGroupSubs();$('#addActionPlan').onclick=()=>addActionPlanRow();fillGroupParts();fillGroupSubs();addActionPlanRow();$('#saveActionBatch').onclick=saveActionBatch}
function fillGroupParts(){const type=$('#baType').value,vals=[...new Set(categoryMasterRows().filter(i=>!type||i.Product_Type===type).map(i=>i.PART).filter(Boolean))];$('#baPart').innerHTML=`<option value="">เลือก PART</option>${vals.map(x=>`<option>${esc(x)}</option>`).join('')}`;fillGroupSubs()}
function fillGroupSubs(){const type=$('#baType').value,part=$('#baPart').value,vals=[...new Set(categoryMasterRows().filter(i=>(!type||i.Product_Type===type)&&(!part||i.PART===part)).map(i=>i.SUB_PART).filter(Boolean))];$('#baSub').innerHTML=`<option value="">เลือก SUB-PART</option>${vals.map(x=>`<option>${esc(x)}</option>`).join('')}`;document.querySelectorAll('[data-action-plan]').forEach(setBatchUoms)}
function batchPlanRow(n){return `<div class="plan-entry" data-action-plan="${n}"><div class="row space"><b>Plan ${n+1}</b><button type="button" class="btn small danger" data-remove-plan>ลบ</button></div><div class="formgrid"><div class="field"><label>วันที่กำหนด</label><input data-a-date type="date" value="${localToday()}"></div><div class="field"><label>ประเภท Action</label><select data-a-kind>${['โทรติดตาม','เข้าพบลูกค้า','เสนอขาย','ส่งตัวอย่าง','ติดตามราคา','อื่น ๆ'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>ประเภทลูกค้า</label><select data-a-customer-type><option value="OLD">ลูกค้าเก่า</option><option value="PROSPECT">Prospect</option></select></div><div class="field" data-a-customer-box><label>เลือกลูกค้าเดิม</label><select data-a-customer></select></div><div class="field hidden" data-a-prospect-box><label>ชื่อ Prospect</label><input data-a-prospect placeholder="พิมพ์ชื่อลูกค้า Prospect"></div><div class="field"><label>Plan ปริมาณ</label><input data-a-qty type="number" min="0" step="0.001"></div><div class="field"><label>หน่วย Plan (Master)</label><select data-a-uom></select></div><div class="field wide"><label>Action / รายละเอียด</label><textarea data-a-detail placeholder="รายละเอียดที่ต้องทำ"></textarea></div></div></div>`}
function addActionPlanRow(){const box=$('#actionPlanRows'),n=box.querySelectorAll('[data-action-plan]').length;box.insertAdjacentHTML('beforeend',batchPlanRow(n));const el=box.lastElementChild;setBatchUoms(el);el.querySelector('[data-a-customer-type]').onchange=e=>{const p=e.target.value==='PROSPECT';el.querySelector('[data-a-customer-box]').classList.toggle('hidden',p);el.querySelector('[data-a-prospect-box]').classList.toggle('hidden',!p)};el.querySelector('[data-remove-plan]').onclick=()=>el.remove()}
function setBatchItemOptions(){document.querySelectorAll('[data-action-plan]').forEach(setBatchUoms)}
function groupUomOptions(type,part,sub,selected=''){const items=active(rows('items')).filter(i=>i.Product_Type===type&&i.PART===part&&i.SUB_PART===sub),codes=new Set(items.map(i=>i.Item_Code)),source=rows('itemUoms').filter(u=>codes.has(u.Item_Code)&&String(u.Active||'Y').toUpperCase()!=='N'),byUom=new Map();for(const u of source){const factors=byUom.get(u.UOM)||new Set();factors.add(Number(u.KG_Per_UOM));byUom.set(u.UOM,factors)}for(const i of items){const u=i.Base_UOM||'MT',factors=byUom.get(u)||new Set();factors.add(Number(i.KG_Per_UOM||1000));byUom.set(u,factors)}for(const [u,f] of [['KG',1],['MT',1000]])if(!byUom.has(u))byUom.set(u,new Set([f]));return [...byUom.entries()].filter(([,f])=>f.size===1&&[...f][0]>0).map(([u,f])=>`<option value="${esc(u)}" data-kg="${[...f][0]}" ${selected===u?'selected':''}>${esc(u)} · 1 ${esc(u)} = ${fmt([...f][0],3)} KG</option>`).join('')}
function customerLovOptionsForGroup(type,part,sub,selectedCustomer=''){const all=rows('customerProducts').filter(x=>String(x.Active||'Y').toUpperCase()!=='N'),links=all.filter(x=>(!x.Product_Type||x.Product_Type===type)&&(!x.PART||x.PART===part)&&(!x.SUB_PART||x.SUB_PART===sub)),codes=new Set(links.map(x=>x.Customer_Code));for(const a of rows('actions')){const i=rows('items').find(x=>x.Item_Code===a.Item_Code)||{};if(a.Customer_Code&&(a.Product_Type||i.Product_Type)===type&&(a.PART||i.PART)===part&&(a.SUB_PART||i.SUB_PART)===sub)codes.add(a.Customer_Code)}for(const p of rows('weeklyPlans')){const i=rows('items').find(x=>x.Item_Code===p.Item_Code)||{};if(p.Customer_Code&&(p.Product_Type||i.Product_Type)===type&&(p.PART||i.PART)===part&&(p.SUB_PART||i.SUB_PART)===sub)codes.add(p.Customer_Code)}return active(rows('customers')).filter(c=>!all.length||codes.has(c.Customer_Code)).map(c=>`<option value="${esc(c.Customer_Code)}" ${c.Customer_Code===selectedCustomer?'selected':''}>${esc(c.Customer_Name)} · ${esc(c.Customer_Code)}</option>`).join('')}
function actionUomMeta(type,part,sub){
 const items=active(rows('items')).filter(i=>i.Product_Type===type&&i.PART===part&&i.SUB_PART===sub),candidates=new Map([['KG','KG'],['MT','MT']]);
 for(const i of items){if(i.Base_UOM)candidates.set(String(i.Base_UOM).trim().toUpperCase(),String(i.Base_UOM).trim());for(const u of rows('itemUoms'))if(String(u.Item_Code)===String(i.Item_Code)&&String(u.Active||'Y').toUpperCase()!=='N'&&String(u.UOM||'').trim())candidates.set(String(u.UOM).trim().toUpperCase(),String(u.UOM).trim())}
 return [...candidates].map(([key,label])=>{const factors=items.map(i=>itemFactorInUom(i,label)),mapped=factors.filter(x=>x>0),uniform=items.length>0&&mapped.length===items.length&&new Set(mapped).size===1;return {key,label,factors,mapped:mapped.length,total:items.length,uniform,factor:uniform?mapped[0]:0}}).filter(x=>x.mapped>0||['KG','MT'].includes(x.key));
}
function actionUomOptions(type,part,sub,selected){
 const meta=actionUomMeta(type,part,sub),html=meta.map(x=>{const note=x.uniform?'1 '+x.label+' = '+fmt(x.factor,3)+' KG':'ตั้ง Conversion '+x.mapped+'/'+x.total+' Item · ระบบคิด Actual ตาม Conversion ราย Item';return '<option value="'+esc(x.label)+'" data-kg="'+(x.uniform?x.factor:'')+'" data-variable="'+(x.uniform?'N':'Y')+'" '+(String(selected||'').toUpperCase()===x.key?'selected':'')+'>'+esc(x.label)+' · '+esc(note)+'</option>'}).join('');
 return html||'<option value="">เลือก UOM หลังเลือกกลุ่มสินค้า</option>';
}
function setBatchUoms(el){el.querySelector('[data-a-uom]').innerHTML=actionUomOptions($('#baType')?.value,$('#baPart')?.value,$('#baSub')?.value);el.querySelector('[data-a-customer]').innerHTML=customerLovOptionsForGroup($('#baType')?.value,$('#baPart')?.value,$('#baSub')?.value)}
function buildFollowupRecords(sale,type,part,sub,entries,batch=id('BATCH')){if(!sale||!type||!part||!sub)throw Error('เลือกพนักงาน Product Type, PART และ SUB-PART ให้ครบ');if(!entries.length)throw Error('เพิ่มรายการ Plan อย่างน้อย 1 รายการ');return entries.map(e=>{const isProspect=e.Customer_Type==='PROSPECT',customer=isProspect?null:rows('customers').find(c=>c.Customer_Code===e.Customer_Code),qty=Number(e.Plan_Qty),due=normDate(e.Due_Date),meta=actionUomMeta(type,part,sub).find(x=>x.key===String(e.Plan_UOM||'').trim().toUpperCase()),kg=meta?.uniform?meta.factor:Number(e.KG_Per_UOM)||0;if(!(qty>0)||!due||!e.Action_Type||!meta||(!isProspect&&!customer)||(isProspect&&!String(e.Prospect_Name||'').trim()))throw Error('กรอกรายละเอียด Plan ให้ครบทุกแถว และเลือก UOM ที่ตั้ง Conversion ในกลุ่มสินค้านี้');if(e.Item_Code){const item=rows('items').find(i=>i.Item_Code===e.Item_Code);if(!item||item.Product_Type!==type||item.PART!==part||item.SUB_PART!==sub)throw Error('สินค้าในรายการไม่ตรงกับกลุ่มสินค้าที่เลือก')}const mt=kg>0?qty*kg/1000:'';return {Action_ID:id('ACT'),Created_Date:localToday(),Due_Date:due,Sale_ID:sale.Sale_ID,Customer_Code:customer?.Customer_Code||'',Item_Code:'',Action_Type:e.Action_Type,Expected_Qty_MT:mt,Status:'OPEN',Result:e.Action_Detail||'',Next_Action:'',Data_Status:'LIVE',Channel:sale.Channel||sale.Team||'',Plan_MT:mt,Closed_Sales_MT:0,Parent_Action_ID:'',Is_Deleted:'N',Manager_Comment:'',Updated_By:me,Updated_At:new Date().toISOString(),Plan_Qty:qty,Plan_UOM:e.Plan_UOM,KG_Per_UOM:kg||'',Plan_KG:kg>0?qty*kg:'',Closed_Sales_Qty:0,Closed_Sales_UOM:e.Plan_UOM,Prospect_ID:'',Prospect_Name:isProspect?String(e.Prospect_Name).trim():'',Batch_ID:batch,Product_Type:type,PART:part,SUB_PART:sub,Next_Action_Date:''}})}
