 const candidateByTab={items:['Product_Type','PART','SUB_PART','Group_Product_Name','Base_UOM','Active'],itemUoms:['UOM','Is_Default','Active'],customers:['Channel','Customer_Segment','Route','Customer_Status','Assigned_Sale_ID','Active'],sales:['Channel','Team','Active'],channels:['Active'],subParts:['PART_ID','Active'],groupProducts:['Product_Type_ID','PART_ID','SUB_PART_ID','Active'],prospects:['Channel','Product_Type','PART','SUB_PART','Status'],customerProducts:['Product_Type','PART','SUB_PART','Group_Product_ID','Active']};
 const filterDefs=(candidateByTab[mtab]||headers).filter(k=>storedHeaders.includes(k)&&allRows.some(x=>String(x[k]||'').trim()));
