 $('#masterContent').innerHTML='<div class="card"><div class="row space"><div><h3>จัดการ Master Data</h3><div class="smallmuted">เพิ่ม · แก้ไข · ปิดใช้ · Import/Export Excel · ใช้หัวคอลัมน์ตามชีต '+esc(TAB[mtab])+'</div></div><div class="row"><input type="file" id="masterUpload" accept=".xlsx,.xls,.csv" class="hidden"><button class="btn" id="masterImport">Import Excel</button><button class="btn" id="masterTemplate">ดาวน์โหลด Template</button><button class="btn" id="masterExport">Export Excel</button><button class="btn primary" id="masterAdd">+ เพิ่มข้อมูล</button></div></div><div class="filter-panel" style="margin:14px 0"><div class="filter-heading"><b>ค้นหาและกรองข้อมูล</b><div class="row"><button class="btn small primary" id="masterFilterApply">กรอง</button><button class="btn small" id="masterFilterClear">ทั้งหมด</button></div></div><div class="filter-row"><div class="filter-control"><label>ค้นหาทุกคอลัมน์</label><input id="masterFilterQ" value="'+esc(state.draftQ??state.q)+'" placeholder="พิมพ์คำค้น"></div>'+controls+'</div><div class="filter-hint">เปิด Dropdown เพื่อเลือกหลายรายการ · All แสดงข้อมูลทั้งหมด · กด “กรอง” เมื่อตั้งค่าเสร็จ</div></div>'+pager+'<div class="tablewrap"><table class="compact-table"><thead><tr>'+headers.map(k=>'<th>'+esc(k)+'</th>').join('')+'<th>จัดการ</th></tr></thead><tbody>'+bodyRows+'</tbody></table></div>'+pager+'</div>';
 document.querySelectorAll('[data-master-search]').forEach(input=>input.oninput=()=>{const q=input.value.trim().toLocaleLowerCase();input.closest('.multi-menu').querySelectorAll('[data-master-option]').forEach(o=>o.style.display=o.textContent.toLocaleLowerCase().includes(q)?'':'none')});
