function targetObjectiveTests(){const t={Year:2026,Month:10,Channel:'ตลาดสด',SUB_PART:'DMS',Plan_MT:70,Data_Status:'LIVE'},items=[{Item_Code:'a',SUB_PART:'DMS'},{Item_Code:'b',SUB_PART:'CCM'}],splits=[{Year:2026,Month:10,Channel:'ตลาดสด',Item_Code:'a',Target_MT:30,Data_Status:'LIVE'},{Year:2026,Month:10,Channel:'ตลาดสด',Item_Code:'b',Target_MT:99,Data_Status:'LIVE'}];return splits.filter(x=>x.Channel===t.Channel&&+x.Year===+t.Year&&+x.Month===+t.Month&&(items.find(i=>i.Item_Code===x.Item_Code)?.SUB_PART||'')===t.SUB_PART).reduce((n,x)=>n+Number(x.Target_MT),0)}
