function targetGroupRows(){
 const typeBy=new Map(rows('productTypes').map(x=>[String(x.Product_Type_ID),x.Product_Type||x.Product_Type_Name||'']));
 const partBy=new Map(rows('parts').map(x=>[String(x.PART_ID),x.PART||x.PART_Name||'']));
 const subBy=new Map(rows('subParts').map(x=>[String(x.SUB_PART_ID),x.SUB_PART||x.SUB_PART_Name||'']));
 const out=[];
 for(const g of active(rows('groupProducts'))){const item=rows('items').find(i=>String(i.Group_Product_ID||'')===String(g.Group_Product_ID||''))||{};
  const x={Group_Product_ID:String(g.Group_Product_ID||''),Group_Product_Name:g.Group_Product_Name||item.Group_Product_Name||item.Item_Name||g.Group_Product_ID||'',Product_Type:g.Product_Type||typeBy.get(String(g.Product_Type_ID))||item.Product_Type||'',PART:g.PART||partBy.get(String(g.PART_ID))||item.PART||'',SUB_PART:g.SUB_PART||subBy.get(String(g.SUB_PART_ID))||item.SUB_PART||''};
  if(x.Group_Product_ID&&x.Product_Type&&x.PART&&x.SUB_PART)out.push(x);
 }
 if(!out.length)for(const i of active(rows('items')))if(i.Group_Product_ID&&!out.some(x=>x.Group_Product_ID===String(i.Group_Product_ID))){const g=rows('groupProducts').find(x=>String(x.Group_Product_ID)===String(i.Group_Product_ID))||{};out.push({Group_Product_ID:String(i.Group_Product_ID),Group_Product_Name:g.Group_Product_Name||i.Group_Product_Name||i.Item_Name||i.Group_Product_ID,Product_Type:i.Product_Type||'',PART:i.PART||'',SUB_PART:i.SUB_PART||''})}
 return out;
}
function targetLevel(t){return String(t?.Target_Level|| (t?.Group_Product_ID?'GROUP_PRODUCT':'SUB_PART')).toUpperCase()==='GROUP_PRODUCT'?'GROUP_PRODUCT':'SUB_PART'}
function groupForTarget(t){const gp=targetGroupRows().find(x=>x.Group_Product_ID===String(t?.Group_Product_ID||''))||{},i=rows('items').find(x=>String(x.Group_Product_ID||'')===String(t?.Group_Product_ID||''))||rows('items').find(x=>x.SUB_PART===t?.SUB_PART&&(!t?.PART||x.PART===t.PART)&&(!t?.Product_Type||x.Product_Type===t.Product_Type))||{};return {Product_Type:t?.Product_Type||gp.Product_Type||i.Product_Type||'',PART:t?.PART||gp.PART||i.PART||'',SUB_PART:t?.SUB_PART||gp.SUB_PART||i.SUB_PART||'',Group_Product_ID:t?.Group_Product_ID||gp.Group_Product_ID||'',Group_Product_Name:t?.Group_Product_Name||gp.Group_Product_Name||i.Group_Product_Name||'',Target_Level:targetLevel(t)}}
function targetScopeKey(t){const g=groupForTarget(t);return targetLevel(t)==='GROUP_PRODUCT'?'GP|'+g.Group_Product_ID:'SUB|'+g.Product_Type+'|'+g.PART+'|'+g.SUB_PART}
function targetDimensionLabel(t){const g=groupForTarget(t);return targetLevel(t)==='GROUP_PRODUCT'?(g.Group_Product_Name||g.Group_Product_ID):g.SUB_PART}
function allocationsForTeam(t){const key=targetScopeKey(t);return rows('targets').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&String(x.Year)===String(t.Year)&&+x.Month===+t.Month&&String(x.Channel||'')===String(t.Channel||'')&&targetLevel(x)===targetLevel(t)&&targetScopeKey(x)===key)}
function targetGroupOptions(type,part,sub){return targetGroupRows().filter(g=>(!type||g.Product_Type===type)&&(!part||g.PART===part)&&(!sub||g.SUB_PART===sub))}
function fillTargetGroupSelect(prefix,old){const level=document.querySelector('#'+prefix+'Level')?.value,wrap=document.querySelector('#'+prefix+'GroupWrap'),sel=document.querySelector('#'+prefix+'Group');if(!sel)return;if(wrap)wrap.style.display=level==='GROUP_PRODUCT'?'':'none';const opts=targetGroupOptions(document.querySelector('#'+prefix+'Type')?.value,document.querySelector('#'+prefix+'Part')?.value,document.querySelector('#'+prefix+'Sub')?.value);sel.innerHTML=opts.map(g=>'<option value="'+esc(g.Group_Product_ID)+'" '+(g.Group_Product_ID===String(old?.Group_Product_ID||'')?'selected':'')+'>'+esc(g.Group_Product_Name)+' · '+esc(g.Group_Product_ID)+'</option>').join('')}
