 function fillSubs(){const gs=categoryMasterRows().filter(x=>(!$('#mtType').value||x.Product_Type===$('#mtType').value)&&(!$('#mtPart').value||x.PART===$('#mtPart').value)),subs=[...new Set(gs.map(x=>x.SUB_PART).filter(Boolean))];$('#mtSub').innerHTML=subs.map(x=>'<option '+(x===old.SUB_PART?'selected':'')+'>'+esc(x)+'</option>').join('');fillTargetGroupSelect('mt',existing)}
